// ============================================================================
// 0. CONFIG — segreti, località e impostazioni
// ============================================================================
// Ordine di priorità: variabile d'ambiente -> valore scritto qui sotto.
//   TELEGRAM_BOT_TOKEN=123456:AA...   GEMINI_API_KEY=AQ...
//   EMAIL_MITTENTE=tua_email@esempio.com
// Su n8n Cloud $env è bloccato: incolla i valori nei fallback.
// ============================================================================

function env(name) {
  try {
    return ($env && $env[name]) ? String($env[name]) : '';
  } catch (e) {
    return ''; // accesso a $env disabilitato
  }
}

const TELEGRAM_BOT_TOKEN = env('TELEGRAM_BOT_TOKEN') || 'INCOLLA_QUI_IL_TOKEN_TELEGRAM';
const GEMINI_API_KEY     = env('GEMINI_API_KEY')     || 'INCOLLA_QUI_LA_API_KEY_GEMINI';

// Chi può chiedere il bollettino. [] = chiunque (sconsigliato: chiunque
// conosca il bot può far partire mail verso indirizzi arbitrari dal tuo SMTP).
const ALLOWED_CHAT_IDS = [];

// ---------------------------------------------------------------------------
// PROFILI — decidono variabili scaricate, fenomeni calcolati e quarta casella
// della mail. La convezione (CAPE + shear) si calcola sempre, ovunque.
// ---------------------------------------------------------------------------
const PROFILI = {
  costa:      { fenomeni: [],                                           riquadro: 'mare' },
  pianura:    { fenomeni: ['nebbia', 'inversione', 'foehn'],             riquadro: 'visibilita' },
  montagna:   { fenomeni: ['neve', 'foehn'],                             riquadro: 'neve' },
  fondovalle: { fenomeni: ['nebbia', 'inversione', 'foehn', 'neve'],     riquadro: 'neve' }
};

const cfg = {
  telegram_token: TELEGRAM_BOT_TOKEN,
  gemini_api_key: GEMINI_API_KEY,

  // Flash Lite è il modello PRIMARIO: 500 richieste/giorno contro le 20 di
  // 3.7 Flash, che resta cablato come fallback sull'Agente Capo.
  gemini_model_micro: 'gemini-3.5-flash-lite',
  gemini_timeout_ms: 120000,
  gemini_max_output_tokens: 4096,
  gemini_retry: 2,

  allowed_chat_ids: ALLOWED_CHAT_IDS,
  max_destinatari: 5,
  // Casella SMTP da cui parte la mail (compare come mittente e in To:).
  email_mittente: env('EMAIL_MITTENTE') || 'tua_email@esempio.com',
  forecast_days: 4,

  // Oltre queste ore il bollettino ufficiale in tabella è considerato vecchio
  // e la mail lo segnala (senza bloccare l'invio).
  ore_max_bollettino: 30,

  profili: PROFILI,

  citta: [
    { id: 'bordighera', nome: 'Bordighera', lat: 43.7794, lon: 7.6697, quota: 10,
      regione: 'liguria', rif: 'Imperia', zona_mare: 'ponente', profilo: 'costa',
      alias: ['bordighera', 'bordi'] },

    { id: 'genova', nome: 'Genova Centro', lat: 44.4056, lon: 8.9463, quota: 20,
      regione: 'liguria', rif: 'Genova', zona_mare: 'centro', profilo: 'costa',
      alias: ['genova', 'genova centro', 'genoa', 'ge'] },

    { id: 'limone', nome: 'Limone Piemonte', lat: 44.2017, lon: 7.5769, quota: 1010,
      regione: 'piemonte', rif: 'CN', profilo: 'montagna',
      alias: ['limone', 'limone piemonte'] },

    { id: 'torino', nome: 'Torino', lat: 45.0703, lon: 7.6869, quota: 239,
      regione: 'piemonte', rif: 'TO', profilo: 'pianura',
      alias: ['torino', 'turin', 'to'] },

    { id: 'garessio', nome: 'Garessio', lat: 44.2033, lon: 8.0203, quota: 621,
      regione: 'piemonte', rif: 'CN', profilo: 'fondovalle',
      alias: ['garessio', 'val tanaro'] }
  ]
};

cfg._warnings = [];
if (cfg.telegram_token.startsWith('INCOLLA_QUI')) cfg._warnings.push('Token Telegram non configurato');
if (cfg.gemini_api_key.startsWith('INCOLLA_QUI')) cfg._warnings.push('API key Gemini non configurata');
if (!cfg.allowed_chat_ids.length) cfg._warnings.push('allowed_chat_ids vuoto: il bot risponde a CHIUNQUE');
if (cfg.email_mittente.endsWith('@esempio.com')) cfg._warnings.push('email_mittente non configurata');

return [{ json: cfg }];

// ============================================================================
// Offset di polling Telegram (memorizzato nello static data del workflow)
// ============================================================================
// ATTENZIONE: $getWorkflowStaticData viene salvato SOLO nelle esecuzioni di
// produzione (workflow attivo). Nei test manuali l'offset non avanza e vedrai
// sempre gli stessi update: è normale, non è un bug.
//
// NB: qui non c'è (più) nessun controllo basato sull'orario. Una versione
// precedente teneva un "telegramStartTime" impostato al momento del primo
// poll schedulato: siccome lo Schedule Trigger non scatta subito
// all'attivazione (aspetta il primo tick, fino a 3 minuti), un messaggio
// mandato subito dopo aver attivato il workflow arrivava con una data
// precedente a quella soglia e veniva scartato per sempre. Il filtro
// "solo il nuovo" ora si basa unicamente sull'offset di Telegram, gestito
// in "Only /start": è la stessa API a garantire che un update_id già
// consumato non venga mai ripresentato, senza bisogno dell'orologio.
// ============================================================================

const data = $getWorkflowStaticData('global');

return [{
  json: {
    offset: Number.isInteger(data.telegramOffset) ? data.telegramOffset : 0
  }
}];

// ============================================================================
// LEGGI RICHIESTA — dal messaggio Telegram a { destinatari, località }
// ============================================================================
// Formato atteso:  <email> <località>
//   mario@esempio.it limone piemonte
//   a@b.com, c@d.it garessio
//
// I token che contengono "@" sono email, tutto il resto unito è il nome della
// località: così funzionano sia più destinatari sia i nomi di due parole.
//
// Le richieste malformate NON vengono buttate via in silenzio: escono con un
// campo `errore` e un nodo a valle risponde su Telegram.
// ============================================================================

const cfg = $('0. Config').first().json;
const data = $getWorkflowStaticData('global');

const updates = Array.isArray($json.result) ? $json.result : [];
if (updates.length === 0) return [];

// Avanza sempre l'offset, anche per i messaggi che scarteremo.
const maxUpdateId = updates.reduce((max, u) => Math.max(max, Number(u.update_id) || 0), 0);
if (maxUpdateId > 0) data.telegramOffset = maxUpdateId + 1;

// Primissima esecuzione: la coda accumulata su Telegram fa da baseline e non
// viene processata. Da qui in poi basta l'offset. (Nessun controllo a orologio:
// aveva una finestra morta all'attivazione.)
if (!data.telegramInitialized) {
  data.telegramInitialized = true;
  return [];
}

const allowed = (cfg.allowed_chat_ids || []).map(Number);
const emailRegex = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;

const out = [];

for (const u of updates) {
  const msg = u.message;
  if (!msg) continue;

  const chatId = Number(msg.chat?.id);
  if (allowed.length > 0 && !allowed.includes(chatId)) continue;

  const text = String(msg.text || '').trim();
  if (!text) continue;

  // I comandi non sono richieste di bollettino: ignorati senza risposta.
  if (text.startsWith('/')) continue;

  const base = {
    text,
    chat_id: chatId,
    user_id: msg.from?.id,
    username: msg.from?.username ?? null,
    update_id: u.update_id
  };

  const token = text.split(/[\s,;]+/).map(t => t.trim()).filter(Boolean);
  const grezzeEmail = token.filter(t => t.includes('@'));
  const restanti = token.filter(t => !t.includes('@'));

  const emails = [...new Set(grezzeEmail.map(e => e.toLowerCase()))];
  const nonValide = emails.filter(e => !emailRegex.test(e));

  if (!emails.length) {
    out.push({ json: { ...base, errore: 'nessuna_email' } });
    continue;
  }
  if (nonValide.length) {
    out.push({ json: { ...base, errore: 'email_non_valida', dettaglio: nonValide.join(', ') } });
    continue;
  }

  const localita = restanti.join(' ').trim();
  if (!localita) {
    out.push({ json: { ...base, errore: 'localita_mancante' } });
    continue;
  }

  out.push({
    json: {
      ...base,
      emails: emails.slice(0, cfg.max_destinatari || 5),
      scartati: Math.max(0, emails.length - (cfg.max_destinatari || 5)),
      localita_richiesta: localita,
      errore: null
    }
  });
}

return out;

// ============================================================================
// RISOLVI LOCALITÀ
// ============================================================================
// Abbina il testo scritto dall'utente a una delle località configurate.
// Confronto insensibile a maiuscole, accenti e punteggiatura, prima esatto e
// poi per prefisso ("limone" trova "Limone Piemonte").
//
// Se non si risolve, l'item prosegue con `errore` e il nodo IF a valle lo manda
// alla risposta Telegram invece che nella pipeline.
// ============================================================================

const cfg = $('0. Config').first().json;
const citta = cfg.citta || [];
const profili = cfg.profili || {};

// "Limone Piemonte" -> "limone piemonte";  "Città" -> "citta"
function normalizza(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const indice = citta.map(c => ({
  citta: c,
  chiavi: [...new Set([c.id, c.nome, ...(c.alias || [])].map(normalizza))]
}));

const elenco = citta.map(c => c.nome).join(', ');

// ---------------------------------------------------------------------------
// Variabili da chiedere a Open-Meteo: si scarica SOLO quello che il profilo
// userà davvero. Costruirle qui tiene il nodo HTTP con una espressione banale.
// ---------------------------------------------------------------------------
const BASE = [
  'temperature_2m', 'apparent_temperature', 'relative_humidity_2m',
  'cloud_cover', 'cloud_cover_high',
  'precipitation', 'precipitation_probability',
  'wind_speed_10m', 'wind_gusts_10m', 'wind_direction_10m',
  'cape', 'convective_inhibition',
  'temperature_850hPa', 'geopotential_height_500hPa', 'temperature_500hPa',
  // servono per lo shear, che si valuta ovunque
  'wind_speed_500hPa', 'wind_direction_500hPa'
];

function variabiliPer(fen) {
  const extra = [];
  if (fen.includes('nebbia') || fen.includes('inversione')) extra.push('dew_point_2m', 'visibility');
  if (fen.includes('foehn')) extra.push('wind_speed_850hPa', 'wind_direction_850hPa');
  if (fen.includes('neve')) extra.push('snowfall', 'snow_depth', 'freezing_level_height');
  return [...new Set([...BASE, ...extra])].join(',');
}

return $input.all().map(item => {
  const j = item.json;

  // Errori già rilevati a monte (email mancante, ecc.): si passa oltre.
  if (j.errore) return { json: { ...j, elenco_localita: elenco } };

  const cercata = normalizza(j.localita_richiesta);

  let trovata = indice.find(e => e.chiavi.includes(cercata));
  if (!trovata) trovata = indice.find(e => e.chiavi.some(k => k.startsWith(cercata) && cercata.length >= 3));
  if (!trovata) trovata = indice.find(e => e.chiavi.some(k => cercata.startsWith(k)));

  if (!trovata) {
    return { json: { ...j, errore: 'localita_sconosciuta', elenco_localita: elenco } };
  }

  const c = trovata.citta;
  const profilo = profili[c.profilo] || { fenomeni: [], riquadro: 'mare' };

  return {
    json: {
      ...j,
      errore: null,
      elenco_localita: elenco,
      citta: c,
      citta_id: c.id,
      regione: c.regione,
      // La convezione si valuta ovunque; il resto dipende dal profilo.
      fenomeni: profilo.fenomeni,
      riquadro: profilo.riquadro,
      hourly: variabiliPer(profilo.fenomeni)
    }
  };
});

// ============================================================================
// MESSAGGIO DI ERRORE PER TELEGRAM
// ============================================================================
// Senza questo ramo una richiesta malformata sparisce nel nulla e chi scrive
// non capisce se il bot sia vivo.
// ============================================================================

return $input.all().map(item => {
  const j = item.json;
  const elenco = j.elenco_localita || '';

  let testo;
  switch (j.errore) {
    case 'nessuna_email':
      testo = '❌ Non ho trovato un indirizzo email nel messaggio.\n\n' +
              'Scrivimi così:\n<email> <località>\n\n' +
              'Esempio: mario@esempio.it garessio';
      break;
    case 'email_non_valida':
      testo = `❌ Indirizzo non valido: ${j.dettaglio}\n\n` +
              'Controlla e riprova con: <email> <località>';
      break;
    case 'localita_mancante':
      testo = '❌ Manca la località.\n\n' +
              'Scrivimi così:\n<email> <località>\n\n' +
              `Località disponibili: ${elenco}`;
      break;
    case 'localita_sconosciuta':
      testo = `❌ Non conosco la località "${j.localita_richiesta}".\n\n` +
              `Località disponibili: ${elenco}`;
      break;
    default:
      testo = '❌ Non sono riuscito a interpretare la richiesta.\n\n' +
              `Scrivimi: <email> <località>\n\nLocalità disponibili: ${elenco}`;
  }

  return { json: { chat_id: j.chat_id, testo } };
});

// ============================================================================
// PREPARA BOLLETTINO UFFICIALE
// ============================================================================
// Prende la riga letta dalla Data table (una per regione, scritta dal workflow
// "Aggiorna Bollettini Ufficiali") e la adatta alla città richiesta:
//
//  - rigenera il testo `clean` tenendo SOLO il riferimento della città
//    (per Torino la sigla TO, non tutte e otto le province: sono token sprecati
//    che confondono il modello)
//  - valuta la freschezza: oltre `ore_max_bollettino` la mail lo segnala
//  - se la riga manca si prosegue coi soli modelli, senza bloccare la mail
// ============================================================================

const cfg = $('0. Config').first().json;
const richiesta = $('Risolvi Località').first().json;
const citta = richiesta.citta;

const riga = $input.first().json || {};

const esito = {
  ...richiesta,
  ufficiale_ok: false,
  ufficiale_nome: null,
  ufficiale_numero: null,
  ufficiale_emissione: null,
  ufficiale_by_date: {},
  ufficiale_tendenza: {},
  ufficiale_clean: '(fonte ufficiale non disponibile in questa esecuzione)',
  ufficiale_nota: ''
};

let doc = null;
try {
  if (riga.testo_bollettino) doc = JSON.parse(riga.testo_bollettino);
} catch (e) {
  esito.ufficiale_nota = 'Riga bollettino illeggibile: bollettino basato sui soli modelli numerici.';
}

if (!doc) {
  if (!esito.ufficiale_nota) {
    esito.ufficiale_nota = `Nessun bollettino ufficiale in tabella per "${citta.regione}": previsione basata sui soli modelli numerici.`;
  }
  return [{ json: esito }];
}

esito.ufficiale_ok = Boolean(doc.ok);
esito.ufficiale_nome = doc.provider === 'arpal' ? 'ARPAL Liguria' : 'ARPA Piemonte';
esito.ufficiale_numero = doc.bollettino || null;
esito.ufficiale_emissione = doc.emissione || null;
esito.ufficiale_by_date = doc.by_date || {};
esito.ufficiale_tendenza = doc.tendenza || {};

// --- freschezza -------------------------------------------------------------
// updatedAt lo mantiene n8n sulla riga; se manca si usa il recuperato_il che
// scrive il parser.
const quando = riga.updatedAt || riga.createdAt || doc.recuperato_il;
if (quando) {
  const ore = (Date.now() - new Date(quando).getTime()) / 3600000;
  esito.ufficiale_ore = Math.round(ore);
  if (ore > (cfg.ore_max_bollettino || 30)) {
    esito.ufficiale_nota = `Bollettino ufficiale non aggiornato da ${Math.round(ore)} h (emissione ${doc.emissione || 'n/d'}).`;
  }
}

// --- testo su misura per la città ------------------------------------------
// Dei riferimenti ufficiali si tiene solo quello della località (più lo zero
// termico, che vale per tutta la regione).
function rifDellaCitta(rif) {
  if (!rif) return '';
  const pezzi = [];
  const mio = rif[citta.rif];
  if (mio && typeof mio === 'object' && 'min' in mio) {
    pezzi.push(`${citta.rif}: ${mio.min}/${mio.max} °C${mio.prob_prec ? ` (prob. prec. ${mio.prob_prec})` : ''}`);
  }
  // Fasce di quota: utili solo dove la quota conta davvero.
  if (citta.profilo === 'montagna' || citta.profilo === 'fondovalle') {
    ['quota_700m', 'quota_1500m', 'quota_2000m'].forEach(k => {
      const v = rif[k];
      if (v && 'min' in v) pezzi.push(`${k.replace('quota_', '').replace('m', ' m')}: ${v.min}/${v.max} °C`);
    });
  }
  if (rif.zero_termico_m) pezzi.push(`zero termico ${rif.zero_termico_m} m`);
  return pezzi.join(' | ');
}

const parti = [
  `BOLLETTINO ${esito.ufficiale_nome} ${doc.bollettino || ''} — emissione ${doc.emissione || 'n/d'}`
];
if (doc.situazione) parti.push(`\nSITUAZIONE ED EVOLUZIONE:\n${doc.situazione}`);

Object.entries(doc.by_date || {}).forEach(([iso, d]) => {
  const rif = rifDellaCitta((doc.rif_localita || {})[iso]);
  parti.push([
    `\n--- ${iso} (${d.etichetta}) — attendibilità dichiarata: ${d.affidabilita || 'n/d'} ---`,
    d.cielo ? `CIELO E FENOMENI: ${d.cielo}` : null,
    d.venti ? `VENTI: ${d.venti}` : null,
    // Il mare interessa solo la costa; lo zero termico solo quota e fondovalle.
    (d.mare && citta.profilo === 'costa') ? `MARE: ${d.mare}` : null,
    (d.zero_termico && citta.profilo !== 'costa') ? `ZERO TERMICO: ${d.zero_termico}` : null,
    d.temperature ? `TENDENZA TERMICA: ${d.temperature}` : null,
    d.umidita ? `UMIDITÀ: ${d.umidita}` : null,
    d.segnalazioni ? `SEGNALAZIONI PROT. CIVILE: ${d.segnalazioni}` : null,
    rif ? `RIFERIMENTI UFFICIALI (${citta.nome}): ${rif}` : null
  ].filter(Boolean).join('\n'));
});

const tend = Object.entries(doc.tendenza || {});
if (tend.length) {
  parti.push('\n--- TENDENZA (giorni successivi, bassa risoluzione) ---');
  tend.forEach(([iso, t]) => {
    parti.push(`${iso}: ${t.previsioni} | temp: ${t.temperature} | venti: ${t.venti}${t.zero_termico ? ` | zero termico: ${t.zero_termico}` : ''} | attendibilità: ${t.affidabilita}`);
  });
}

esito.ufficiale_clean = parti.join('\n').trim();

return [{ json: esito }];

// ============================================================================
// AGGREGATORE DETERMINISTICO (una sola località)
// ============================================================================
// Tutto ciò che è numerico nasce qui. L'LLM non produce mai numeri: li racconta.
//
// Cosa fa:
//  - lavora su una città sola, quella scelta dal bot
//  - calcola qui i fenomeni locali, secondo il profilo della località:
//    nebbia, foehn, inversione termica, neve e zero termico
//  - classifica la convezione con CAPE **e shear**, non col CAPE da solo:
//    2330 J/kg con 0 mm di pioggia non sono un temporale, sono energia
//    inespressa, e senza lo shear non c'è modo di distinguerlo
// ============================================================================

const cfg = $('0. Config').first().json;
// Il contesto arriva dal nodo precedente, che contiene GIÀ sia la richiesta
// risolta sia il bollettino ufficiale letto dalla Data table: ripartire da
// "Risolvi Località" perderebbe i campi ufficiale_*.
const contesto = $('Prepara Bollettino Ufficiale').first().json;
const citta = contesto.citta;
const fenomeni = contesto.fenomeni || [];

// Con UNA coordinata Open-Meteo risponde con un oggetto, non con un array.
const primo = $input.first().json ?? {};
const loc = Array.isArray(primo) ? primo[0] : primo;

if (!loc || !loc.hourly) {
  throw new Error('Risposta Open-Meteo non valida o vuota: impossibile aggregare i dati.');
}

// --- catene di priorità modelli --------------------------------------------
// AROME HD ha ~48 h di corsa: oltre quell'orizzonte i valori sono null e si
// scala da sé sul modello successivo, ora per ora. AROME inoltre non fornisce
// cloud_cover totale, probabilità, CIN e livelli isobarici: per quelle
// grandezze la catena parte direttamente da ICON-D2 / ECMWF.
const M_SUOLO   = ['meteofrance_arome_france_hd', 'icon_d2', 'italia_meteo_arpae_icon_2i', 'ecmwf_ifs025', 'gfs_seamless'];
const M_NUBI    = ['icon_d2', 'italia_meteo_arpae_icon_2i', 'ecmwf_ifs025', 'gfs_seamless'];
const M_PROB    = ['ecmwf_ifs025', 'gfs_seamless'];
const M_CONV    = ['icon_d2', 'italia_meteo_arpae_icon_2i', 'gfs_seamless', 'ecmwf_ifs025'];
const M_QUOTA   = ['ecmwf_ifs025', 'gfs_seamless', 'icon_d2', 'italia_meteo_arpae_icon_2i'];
const M_PIOGGIA = ['meteofrance_arome_france_hd', 'icon_d2', 'italia_meteo_arpae_icon_2i'];
// Neve, zero termico e visibilità: solo ICON-D2 e ICON-2I li danno su tutte le
// località; GFS come rete di sicurezza.
const M_NEVE    = ['icon_d2', 'italia_meteo_arpae_icon_2i', 'gfs_seamless'];

function val(h, base, models, i) {
  for (const m of models) {
    const arr = h[`${base}_${m}`];
    if (Array.isArray(arr)) {
      const v = arr[i];
      if (v !== null && v !== undefined) return v;
    }
  }
  const plain = h[base];
  if (Array.isArray(plain) && plain[i] !== null && plain[i] !== undefined) return plain[i];
  return null;
}

// Per la pioggia il "primo non nullo" sottostima: si prende lo scenario più
// cautelativo tra i modelli ad alta risoluzione.
function maxVal(h, base, models, i) {
  let out = null;
  for (const m of models) {
    const arr = h[`${base}_${m}`];
    const v = Array.isArray(arr) ? arr[i] : null;
    if (v !== null && v !== undefined && (out === null || v > out)) out = v;
  }
  return out;
}

function normalizeWind(dir, speed) {
  if (dir == null || speed == null || speed <= 5) return 'Variabile';
  const d = ((Math.round(dir) % 360) + 360) % 360;
  if (d >= 337 || d <= 22) return 'N';
  if (d <= 67) return 'NE';
  if (d <= 112) return 'E';
  if (d <= 157) return 'SE';
  if (d <= 202) return 'S';
  if (d <= 247) return 'SO';
  if (d <= 292) return 'O';
  return 'NO';
}

// [9,10,11,15,16] -> "09-11, 15-16"
function finestre(ore, maxBlocchi = 2) {
  if (!ore.length) return null;
  const s = [...new Set(ore)].sort((a, b) => a - b);
  const blocchi = [];
  let start = s[0], prev = s[0];
  for (let i = 1; i < s.length; i++) {
    if (s[i] === prev + 1) { prev = s[i]; continue; }
    blocchi.push([start, prev]);
    start = prev = s[i];
  }
  blocchi.push([start, prev]);
  const p = n => String(n).padStart(2, '0');
  return blocchi
    .sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]))
    .slice(0, maxBlocchi)
    .sort((a, b) => a[0] - b[0])
    .map(([a, b]) => (a === b ? `${p(a)}:00` : `${p(a)}-${p(b)}`))
    .join(', ');
}

function cieloSintetico(pct) {
  if (pct == null) return 'n/d';
  if (pct < 20) return 'sereno';
  if (pct < 40) return 'poco nuvoloso';
  if (pct < 65) return 'parzialmente nuvoloso';
  if (pct < 85) return 'molto nuvoloso';
  return 'coperto';
}

// Direzione meteorologica (da dove viene) -> componenti u,v in m/s
function componenti(spdKmh, dirDeg) {
  const s = spdKmh / 3.6;
  const r = (dirDeg * Math.PI) / 180;
  return [-s * Math.sin(r), -s * Math.cos(r)];
}

// Deep-layer shear: differenza VETTORIALE fra vento a 500 hPa e vento a 10 m.
// È ciò che distingue un rovescio isolato da una cella organizzata.
function shearMs(spd500, dir500, spd10, dir10) {
  if ([spd500, dir500, spd10, dir10].some(v => v === null || v === undefined)) return null;
  const [u1, v1] = componenti(spd500, dir500);
  const [u2, v2] = componenti(spd10, dir10);
  return Math.hypot(u1 - u2, v1 - v2);
}

// La sola energia non basta a fare un temporale: se nessun modello ad alta
// risoluzione bagna e la probabilità resta bassa, quel CAPE è energia
// INESPRESSA (tappata dall'inibizione o priva di forzante), non un evento.
function classificaConvezione(cape, shear, rainTot, prob, cin) {
  if (cape == null || cape < 300) return 'assente';

  const asciutto = rainTot < 0.2 && prob < 30;
  const tappata = cin !== null && cin > 100 && rainTot < 1;
  if (asciutto || tappata) return 'inespressa';

  if (shear == null) return 'incerta';
  if (cape >= 500 && shear > 20) return 'organizzata';
  if (cape >= 500 && shear >= 10) return 'celle possibili';
  return 'isolata';
}

const media = a => (a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : null);
const ORE_DETTAGLIO = [0, 3, 6, 9, 12, 15, 18, 21];

const vuoleNebbia     = fenomeni.includes('nebbia');
const vuoleFoehn      = fenomeni.includes('foehn');
const vuoleInversione = fenomeni.includes('inversione');
const vuoleNeve       = fenomeni.includes('neve');

const h = loc.hourly || {};
const times = h.time || [];
const daysMap = {};

for (let i = 0; i < times.length; i++) {
  const dateStr = times[i].substring(0, 10);
  const hour = Number(times[i].substring(11, 13));

  if (!daysMap[dateStr]) {
    daysMap[dateStr] = {
      date: dateStr, orarie: [], dettaglio: [],
      tmin: null, tmax: null, appMin: null, appMax: null,
      windMax: 0, windDirNum: null, gustMax: 0, gustHour: null,
      rainTot: 0, rainMaxH: 0, oreRain: [], probMax: 0,
      capeMax: 0, cinMin: null, shearAlPicco: null, shearMax: 0,
      nubi: [], nubiGiorno: [], nubiAlte: [], umid: [], oreValide: 0,
      // fenomeni
      oreNebbia: [], oreFoschia: [], visMin: null,
      oreFoehn: [], oreInversione: [],
      neveTot: 0, neveMaxDepth: 0, zeroMin: null, zeroMax: null
    };
  }
  const day = daysMap[dateStr];

  // ---- lettura oraria (tutte le 24 ore) ----------------------------------
  const t     = val(h, 'temperature_2m', M_SUOLO, i);
  const tApp  = val(h, 'apparent_temperature', M_SUOLO, i);
  const wspd  = val(h, 'wind_speed_10m', M_SUOLO, i);
  const gust  = val(h, 'wind_gusts_10m', M_SUOLO, i);
  const wdir  = val(h, 'wind_direction_10m', M_SUOLO, i);
  const rain  = maxVal(h, 'precipitation', M_PIOGGIA, i) ?? val(h, 'precipitation', M_SUOLO, i) ?? 0;
  const prob  = val(h, 'precipitation_probability', M_PROB, i) ?? 0;
  const nubi  = val(h, 'cloud_cover', M_NUBI, i);
  const nAlte = val(h, 'cloud_cover_high', M_NUBI, i);
  const rh    = val(h, 'relative_humidity_2m', M_SUOLO, i);
  const cape  = val(h, 'cape', M_CONV, i);
  const cin   = val(h, 'convective_inhibition', M_CONV, i);
  const t850  = val(h, 'temperature_850hPa', M_QUOTA, i);
  const s500  = val(h, 'wind_speed_500hPa', M_QUOTA, i);
  const d500  = val(h, 'wind_direction_500hPa', M_QUOTA, i);

  if (t !== null) {
    day.oreValide++;
    day.tmin = day.tmin === null ? t : Math.min(day.tmin, t);
    day.tmax = day.tmax === null ? t : Math.max(day.tmax, t);
  }
  if (tApp !== null) {
    day.appMin = day.appMin === null ? tApp : Math.min(day.appMin, tApp);
    day.appMax = day.appMax === null ? tApp : Math.max(day.appMax, tApp);
  }
  if (wspd !== null && wspd > day.windMax) { day.windMax = wspd; day.windDirNum = wdir; }
  if (gust !== null && gust > day.gustMax) { day.gustMax = gust; day.gustHour = hour; }
  if (rain > 0) { day.rainTot += rain; day.oreRain.push(hour); }
  if (rain > day.rainMaxH) day.rainMaxH = rain;
  if (prob > day.probMax) day.probMax = prob;
  if (cin !== null && (day.cinMin === null || cin < day.cinMin)) day.cinMin = cin;
  if (nubi !== null) {
    day.nubi.push(nubi);
    if (hour >= 7 && hour <= 20) day.nubiGiorno.push(nubi);
  }
  if (nAlte !== null) day.nubiAlte.push(nAlte);
  if (rh !== null) day.umid.push(rh);
  day.orarie.push({ hour, gust: gust ?? 0 });

  // ---- convezione: lo shear va letto NELL'ORA di massimo CAPE -------------
  const sh = shearMs(s500, d500, wspd, wdir);
  if (sh !== null && sh > day.shearMax) day.shearMax = sh;
  if (cape !== null && cape > day.capeMax) {
    day.capeMax = cape;
    day.shearAlPicco = sh;
  }

  // ---- fenomeni locali ----------------------------------------------------
  if (vuoleNebbia) {
    const vis = val(h, 'visibility', M_NEVE, i);
    const td  = val(h, 'dew_point_2m', M_SUOLO, i);
    if (vis !== null) {
      if (day.visMin === null || vis < day.visMin) day.visMin = vis;
      if (vis < 1000) day.oreNebbia.push(hour);
      else if (vis < 5000) day.oreFoschia.push(hour);
    }
    // Conferma indipendente da irraggiamento notturno: cielo sereno, aria
    // ferma e rugiada vicina alla temperatura. Serve perché i modelli a scala
    // regionale sottostimano regolarmente la nebbia di pianura.
    const notte = hour >= 22 || hour <= 9;
    if (notte && t !== null && td !== null && wspd !== null && nubi !== null &&
        (t - td) < 2.5 && wspd < 6 && nubi < 40 && !day.oreNebbia.includes(hour)) {
      day.oreFoschia.push(hour);
    }
  }

  if (vuoleFoehn) {
    const s850 = val(h, 'wind_speed_850hPa', M_QUOTA, i);
    const d850 = val(h, 'wind_direction_850hPa', M_QUOTA, i);
    if (s850 !== null && d850 !== null && rh !== null) {
      const daNordOvest = d850 >= 270 && d850 <= 360;
      if (daNordOvest && s850 > 25 && rh < 45) day.oreFoehn.push(hour);
    }
  }

  // Proxy di inversione: T850 (~1500 m) più calda del suolo nelle ore notturne.
  // Ha senso solo in pianura e nei fondovalle, dove l'aria fredda ristagna.
  if (vuoleInversione && citta.quota < 800 && hour <= 7) {
    if (t !== null && t850 !== null && t850 > t + 2) day.oreInversione.push(hour);
  }

  if (vuoleNeve) {
    const neve = val(h, 'snowfall', M_NEVE, i);
    const spess = val(h, 'snow_depth', M_NEVE, i);
    const zero = val(h, 'freezing_level_height', M_NEVE, i);
    if (neve !== null && neve > 0) day.neveTot += neve;
    if (spess !== null && spess > day.neveMaxDepth) day.neveMaxDepth = spess;
    if (zero !== null) {
      day.zeroMin = day.zeroMin === null ? zero : Math.min(day.zeroMin, zero);
      day.zeroMax = day.zeroMax === null ? zero : Math.max(day.zeroMax, zero);
    }
  }

  // ---- riga di dettaglio ogni 3 h -----------------------------------------
  if (!ORE_DETTAGLIO.includes(hour)) continue;

  const zRaw = val(h, 'geopotential_height_500hPa', M_QUOTA, i);
  const z500 = zRaw == null ? '-' : Math.round(zRaw / 10);
  const t500 = val(h, 'temperature_500hPa', M_QUOTA, i);

  let riga = ` ${String(hour).padStart(2, '0')}h | Z500:${z500} T500:${t500 != null ? t500.toFixed(1) : '-'} T850:${t850 != null ? t850.toFixed(1) : '-'}` +
    ` | T:${t != null ? t.toFixed(1) : '-'}°C (perc.${tApp != null ? tApp.toFixed(1) : '-'}°C) UR:${rh != null ? Math.round(rh) : '-'}%` +
    ` | Nubi:${nubi != null ? Math.round(nubi) : '-'}% (alte ${nAlte != null ? Math.round(nAlte) : '-'}%)` +
    ` | Pioggia:${rain.toFixed(1)}mm/h Prob:${Math.round(prob)}%` +
    ` | CAPE:${cape != null ? Math.round(cape) : '-'} CIN:${cin != null ? Math.round(cin) : '-'} Shear:${sh != null ? sh.toFixed(0) : '-'}m/s` +
    ` | Vento:${wspd != null ? Math.round(wspd) : '-'}km/h Raff:${gust != null ? Math.round(gust) : '-'}km/h Dir:${wdir != null ? Math.round(wdir) : '-'}°`;

  if (vuoleNeve) {
    const zero = val(h, 'freezing_level_height', M_NEVE, i);
    const neve = val(h, 'snowfall', M_NEVE, i);
    riga += ` | Zero:${zero != null ? Math.round(zero) : '-'}m Neve:${neve != null ? neve.toFixed(1) : '-'}cm`;
  }
  if (vuoleNebbia) {
    const vis = val(h, 'visibility', M_NEVE, i);
    riga += ` | Vis:${vis != null ? Math.round(vis) : '-'}m`;
  }

  day.dettaglio.push(riga);
}

// Scarta le giornate incomplete in coda.
const giorniOrdinati = Object.keys(daysMap).sort()
  .filter(d => daysMap[d].oreValide >= 12)
  .slice(0, cfg.forecast_days || 4);

let testo = '';
const stats = {};

for (const d of giorniOrdinati) {
  const day = daysMap[d];
  const dirStr = normalizeWind(day.windDirNum, day.windMax);
  const nubiMedia = media(day.nubi);
  const nubiDiurne = media(day.nubiGiorno);
  const umidMedia = media(day.umid);

  const sogliaG = day.gustMax * 0.85;
  const oreVento = day.gustMax >= 20 ? day.orarie.filter(r => r.gust >= sogliaG).map(r => r.hour) : [];

  const classe = classificaConvezione(
    day.capeMax, day.shearAlPicco,
    day.rainTot, day.probMax,
    day.cinMin === null ? null : day.cinMin
  );

  const s = {
    tmin: day.tmin !== null ? Number(day.tmin.toFixed(1)) : null,
    tmax: day.tmax !== null ? Number(day.tmax.toFixed(1)) : null,
    perc_min: day.appMin !== null ? Number(day.appMin.toFixed(1)) : null,
    perc_max: day.appMax !== null ? Number(day.appMax.toFixed(1)) : null,
    wind: Math.round(day.windMax),
    gust: Math.round(day.gustMax),
    dir: dirStr,
    rain_tot: Number(day.rainTot.toFixed(1)),
    rain_max_h: Number(day.rainMaxH.toFixed(1)),
    prob: Math.round(day.probMax),
    nuvolosita: nubiMedia,
    nuvolosita_diurna: nubiDiurne,
    nuvolosita_alta: media(day.nubiAlte),
    cielo: cieloSintetico(nubiDiurne ?? nubiMedia),
    umidita: umidMedia,
    cape_max: Math.round(day.capeMax),
    cin_min: day.cinMin !== null ? Math.round(day.cinMin) : null,
    shear_ms: day.shearAlPicco !== null ? Number(day.shearAlPicco.toFixed(1)) : null,
    convezione: classe,
    finestra_pioggia: finestre(day.oreRain),
    finestra_vento: finestre(oreVento)
  };

  // --- fenomeni locali nel riepilogo giornaliero ---------------------------
  if (vuoleNebbia) {
    s.nebbia = day.oreNebbia.length ? finestre(day.oreNebbia) : null;
    s.foschia = day.oreFoschia.length ? finestre(day.oreFoschia) : null;
    s.vis_min = day.visMin !== null ? Math.round(day.visMin) : null;
  }
  if (vuoleFoehn) s.foehn = day.oreFoehn.length ? finestre(day.oreFoehn) : null;
  if (vuoleInversione) s.inversione = day.oreInversione.length ? finestre(day.oreInversione) : null;
  if (vuoleNeve) {
    s.neve_cm = Number(day.neveTot.toFixed(1));
    s.neve_al_suolo_cm = Number((day.neveMaxDepth * 100).toFixed(0)); // snow_depth è in m
    s.zero_termico_min = day.zeroMin !== null ? Math.round(day.zeroMin) : null;
    s.zero_termico_max = day.zeroMax !== null ? Math.round(day.zeroMax) : null;
  }

  stats[d] = s;

  testo += `\n=== GIORNO: ${d} ===\n`;
  testo += `[VALORI AGGREGATI DETERMINISTICI — calcolati su tutte le 24 h]\n`;
  testo += `- Tmin/Tmax: ${s.tmin ?? '-'} / ${s.tmax ?? '-'} °C (percepita ${s.perc_min ?? '-'} / ${s.perc_max ?? '-'} °C)\n`;
  testo += `- Cielo: ${s.cielo} (copertura media diurna ${nubiDiurne ?? '-'} %, nubi alte ${s.nuvolosita_alta ?? '-'} %) | Umidità relativa media: ${umidMedia ?? '-'} %\n`;
  testo += `- Vento max: ${s.wind} km/h da ${dirStr} | raffica max: ${s.gust} km/h${s.finestra_vento ? ` | rinforzi ore ${s.finestra_vento}` : ''}\n`;
  testo += `- Pioggia TOTALE giornaliera: ${s.rain_tot} mm | intensità oraria max: ${s.rain_max_h} mm/h | probabilità max: ${s.prob} %`;
  testo += s.finestra_pioggia ? ` | fenomeni ore ${s.finestra_pioggia}\n` : ` | nessuna ora con precipitazione prevista\n`;
  testo += `- Convezione: ${classe.toUpperCase()} (CAPE max ${s.cape_max} J/kg, CIN min ${s.cin_min ?? '-'} J/kg, shear al picco ${s.shear_ms ?? '-'} m/s)\n`;

  if (vuoleNeve) {
    testo += `- Zero termico: ${s.zero_termico_min ?? '-'}–${s.zero_termico_max ?? '-'} m | Neve prevista: ${s.neve_cm} cm | Manto al suolo: ${s.neve_al_suolo_cm} cm\n`;
  }
  if (vuoleNebbia) {
    testo += `- Visibilità minima: ${s.vis_min ?? '-'} m`;
    testo += s.nebbia ? ` | NEBBIA ore ${s.nebbia}` : '';
    testo += s.foschia ? ` | foschia ore ${s.foschia}` : '';
    testo += (!s.nebbia && !s.foschia) ? ' | nessuna riduzione di visibilità' : '';
    testo += '\n';
  }
  if (vuoleFoehn) {
    testo += `- Foehn: ${s.foehn ? `condizioni favorevoli ore ${s.foehn}` : 'nessun segnale'}\n`;
  }
  if (vuoleInversione) {
    testo += `- Inversione termica notturna (proxy T850 vs suolo): ${s.inversione ? `probabile ore ${s.inversione}` : 'non indicata'}\n`;
  }

  testo += `\n[DETTAGLIO ORARIO OGNI 3 H]\n`;
  testo += day.dettaglio.join('\n') + '\n';
}

return [{
  json: {
    ...contesto,
    dati_modelli: testo,
    raw_stats: stats,
    giorni_previsti: giorniOrdinati,
    quota_modello: loc.elevation ?? null
  }
}];

// ============================================================================
// MICRO-AGENTI (2 chiamate: quota + suolo della località richiesta)
// ============================================================================
// Girano a ogni richiesta perché i dati numerici cambiano nell'arco della
// giornata, mentre il bollettino ufficiale no (quello sta in cache).
//
// Quota: 2 chiamate qui + 1 dell'Agente Capo = 3 per bollettino, tutte su
// Flash Lite (500 richieste/giorno) -> ~166 bollettini. 3.7 Flash, che si
// ferma a 20 al giorno, resta solo come fallback dell'Agente Capo.
// ============================================================================

const cfg = $('0. Config').first().json;
const contesto = $input.first().json;
const citta = contesto.citta;

const apiKey = cfg.gemini_api_key;
const model = cfg.gemini_model_micro || 'gemini-3.5-flash-lite';
const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;

if (!apiKey || apiKey.startsWith('INCOLLA_QUI')) {
  throw new Error('API key Gemini non configurata nel nodo "0. Config".');
}

const ctx = this; // serve per this.helpers.httpRequest
const sleep = ms => new Promise(r => setTimeout(r, ms));
const dati = contesto.dati_modelli || '';
const fenomeni = contesto.fenomeni || [];

// Righe extra chieste al micro-agente SUOLO solo dove il profilo le prevede.
const righeFenomeni = [
  fenomeni.includes('nebbia')
    ? '  * Visibilità: [Nebbia o foschia con le ore già calcolate, oppure "visibilità buona"]' : null,
  fenomeni.includes('foehn')
    ? '  * Foehn: [Riporta la finestra oraria se indicata, altrimenti "nessun segnale"]' : null,
  fenomeni.includes('inversione')
    ? '  * Inversione notturna: [Solo se indicata nei dati; è un proxy, non una misura]' : null,
  fenomeni.includes('neve')
    ? '  * Zero termico e neve: [Quota dello zero termico e neve prevista, valori pre-calcolati]' : null
].filter(Boolean).join('\n');

const promptQuota = `Sei l'Agente Specialista QUOTA per ${citta.nome} (${citta.quota} m s.l.m.).
Analizza i dati pre-calcolati:
${dati}

REGOLE TASSATIVE:
Lavora esclusivamente giorno per giorno. Non ricalcolare nulla: i valori sono già definitivi.

Sulla convezione usa la classificazione già presente nei dati, che combina
energia (CAPE), inibizione (CIN), shear e pioggia effettiva:
- ASSENTE: niente da segnalare.
- INESPRESSA: c'è energia ma nessun modello bagna. NON è un temporale: è
  energia bloccata o priva di forzante. Vietato trasformarla in allarme.
- ISOLATA: rovesci brevi e localizzati, poco organizzati.
- CELLE POSSIBILI / ORGANIZZATA: lo shear regge le celle, possibili colpi
  di vento associati.

TEMPLATE PER OGNI GIORNO:
* **[Data MM-GG]:**
  * Sinottica & 850hPa: [Stato di T850, Z500 e vento in quota, max 20 parole]
  * Giudizio Termodinamico: [Classe di convezione e cosa comporta davvero. Max 15 parole.]`;

const promptSuolo = `Sei l'Agente Specialista SUOLO per ${citta.nome} (${citta.quota} m s.l.m.).
Analizza i dati pre-calcolati:
${dati}

REGOLE TASSATIVE:
Lavora esclusivamente giorno per giorno. Usa i valori pre-calcolati così come
sono, non ricalcolarli e non arrotondarli.

TEMPLATE PER OGNI GIORNO:
* **[Data MM-GG]:**
  * Tmin_Tmax: [Valori pre-calcolati, inclusa la percepita]
  * Cielo: [Copertura media e come evolve nella giornata]
  * Vento_Previsto: [Valori pre-calcolati con direzione]
  * Pioggia_Prevista: [Totale giornaliero e intensità oraria max]
${righeFenomeni}
  * Finestra Fenomeni: [Riporta le finestre orarie già calcolate. Se non ci
    sono fenomeni scrivi "Fenomeni assenti". Max 12 parole.]`;

async function callLlm(key, promptText) {
  const tentativi = 1 + (cfg.gemini_retry ?? 2);
  let ultimoErrore;

  for (let n = 0; n < tentativi; n++) {
    try {
      const res = await ctx.helpers.httpRequest({
        url,
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-goog-api-key': apiKey },
        body: {
          contents: [{ parts: [{ text: promptText }] }],
          generationConfig: {
            temperature: 0,
            maxOutputTokens: cfg.gemini_max_output_tokens || 4096,
            thinkingConfig: { thinkingBudget: -1 }
          }
        },
        json: true,
        timeout: cfg.gemini_timeout_ms || 120000
      });

      const blocco = res.promptFeedback?.blockReason;
      if (blocco) throw new Error(`prompt bloccato dai filtri (${blocco})`);

      const cand = res.candidates?.[0];
      const parts = cand?.content?.parts || [];
      const testo = parts.filter(p => !p.thought).map(p => p.text || '').join('').trim();

      if (!testo) {
        // MAX_TOKENS = budget consumato tutto dal reasoning: alzare
        // gemini_max_output_tokens in "0. Config".
        throw new Error(`nessun testo utile (finishReason: ${cand?.finishReason || 'risposta vuota'})`);
      }
      return { key, text: testo };
    } catch (error) {
      ultimoErrore = error;
      const codice = error.statusCode || error.httpCode || error.response?.status || 0;
      const ritentabile = [408, 409, 425, 429, 500, 502, 503, 504].includes(Number(codice))
        || /timeout|ECONNRESET|ETIMEDOUT|socket hang up/i.test(error.message || '');
      if (n === tentativi - 1 || !ritentabile) break;
      await sleep(1500 * Math.pow(2, n)); // 1.5s, 3s, 6s
    }
  }
  throw new Error(`[${key}] ${ultimoErrore?.message || 'errore sconosciuto'}`);
}

const job = [
  { key: 'rep_quota', prompt: promptQuota },
  { key: 'rep_suolo', prompt: promptSuolo }
];

const esiti = await Promise.allSettled(job.map(j => callLlm(j.key, j.prompt)));

const falliti = [];
const reports = {};
esiti.forEach((e, i) => {
  const key = job[i].key;
  if (e.status === 'fulfilled') {
    reports[key] = e.value.text;
  } else {
    // Degrado morbido: l'Agente Capo riceve una nota esplicita invece di un
    // buco silenzioso, che riempirebbe di invenzioni.
    reports[key] = '(report non disponibile: micro-agente in errore)';
    falliti.push(`${key}: ${e.reason?.message || e.reason}`);
  }
});

if (falliti.length === job.length) {
  throw new Error('Entrambi i micro-agenti hanno fallito:\n' + falliti.join('\n'));
}

return [{ json: { ...contesto, ...reports, micro_agenti_falliti: falliti } }];

// ============================================================================
// VALIDATORE E SOVRASCRITTURA NUMERICA
// ============================================================================
// La lista dei giorni la decide lo SCRIPT, non l'LLM: se il modello salta una
// giornata o sbaglia una data, la mail resta corretta. I numeri vengono tutti
// riscritti da qui, l'LLM contribuisce solo il testo.
// ============================================================================

const cfg = $('0. Config').first().json;
const rawText = String($input.first().json.text || '');

// L'Agente Capo (chainLlm) restituisce SOLO { text }: il contesto va ripreso
// dal nodo che l'ha prodotto.
const contesto = $('Micro-Agenti').first().json;
const citta = contesto.citta;
const riquadro = contesto.riquadro;

// --- 1. estrazione del JSON -------------------------------------------------
function estraiJson(testo) {
  let t = testo.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const primo = t.indexOf('{');
  const ultimo = t.lastIndexOf('}');
  if (primo === -1 || ultimo === -1 || ultimo <= primo) return null;
  t = t.substring(primo, ultimo + 1);
  try { return JSON.parse(t); } catch (e) { /* si tenta la ripulitura */ }
  try { return JSON.parse(t.replace(/,\s*([}\]])/g, '$1')); } catch (e) { return null; }
}

const data = estraiJson(rawText);
if (!data) {
  throw new Error(
    'JSON non valido dall\'Agente Capo. Primi 400 caratteri della risposta:\n' + rawText.slice(0, 400)
  );
}

// --- 2. utilità -------------------------------------------------------------
const GIORNI_IT = ['Domenica', 'Lunedì', 'Martedì', 'Mercoledì', 'Giovedì', 'Venerdì', 'Sabato'];

function titoloIta(iso) {
  const d = new Date(`${iso}T12:00:00Z`);
  if (isNaN(d)) return iso;
  return `${GIORNI_IT[d.getUTCDay()]} (${iso.slice(8, 10)}-${iso.slice(5, 7)})`;
}

// Tiene solo le parti della riga MARE pertinenti alla zona della località.
// "Mosso a Levante, poco mosso ovunque la sera" + ponente -> "Poco mosso ovunque la sera"
function mareZona(testo, zona) {
  if (!testo) return '';
  const zone = ['ponente', 'centro', 'levante'];
  const altre = zone.filter(z => z !== zona);
  const proprie = [], generiche = [];

  for (const c of testo.split(',').map(s => s.trim()).filter(Boolean)) {
    const low = c.toLowerCase();
    if (altre.some(z => low.includes(z))) continue;
    if (low.includes(zona)) proprie.push(c); else generiche.push(c);
  }
  const scelte = proprie.length ? proprie.concat(generiche) : generiche;
  if (!scelte.length) return '';
  const s = scelte.join(', ').replace(/\s+/g, ' ').trim();
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function ripulisciTesto(s) {
  return String(s || '')
    .replace(/si registrer[àa]/gi, 'si prevede')
    .replace(/registrat([oaie])/gi, (_, v) => ({ o: 'previsto', a: 'prevista', i: 'previsti', e: 'previste' }[v.toLowerCase()]))
    .replace(/\s+/g, ' ')
    .trim();
}

// --- 3. dati deterministici -------------------------------------------------
const raw_stats = contesto.raw_stats || {};
const dateKeys = (contesto.giorni_previsti || []).length
  ? contesto.giorni_previsti
  : Object.keys(raw_stats).sort();

const byDate = contesto.ufficiale_by_date || {};
const tendenza = contesto.ufficiale_tendenza || {};
const giorniLlm = Array.isArray(data.giorni) ? data.giorni : [];

const giorni = dateKeys.map((iso, index) => {
  // abbinamento: data_iso -> posizione
  let g = giorniLlm.find(x => String(x.data_iso || '').trim() === iso) || giorniLlm[index] || {};

  const s = raw_stats[iso] || {};
  const uff = byDate[iso] || {};
  const tend = tendenza[iso] || {};

  // --- la quarta metrica dipende dal profilo della località ----------------
  const extra = {};
  if (riquadro === 'mare') {
    let mare = mareZona(uff.mare, citta.zona_mare);
    if (!mare) mare = 'Non disponibile';
    extra.mare = mare;
  } else if (riquadro === 'neve') {
    extra.zero_termico_min = s.zero_termico_min ?? null;
    extra.zero_termico_max = s.zero_termico_max ?? null;
    extra.neve_cm = s.neve_cm ?? 0;
    extra.neve_al_suolo_cm = s.neve_al_suolo_cm ?? 0;
  } else if (riquadro === 'visibilita') {
    extra.vis_min = s.vis_min ?? null;
    extra.nebbia = s.nebbia || null;
    extra.foschia = s.foschia || null;
  }

  return {
    data_iso: iso,
    titolo: titoloIta(iso),
    descrizione: ripulisciTesto(g.descrizione) || '(descrizione non disponibile per questa giornata)',

    // --- numeri: sempre e solo dallo script -------------------------------
    tmin: s.tmin ?? null,
    tmax: s.tmax ?? null,
    perc_min: s.perc_min ?? null,
    perc_max: s.perc_max ?? null,
    vento_dir: s.dir || 'Variabile',
    vento_kmh: s.wind ?? null,
    raffiche_kmh: s.gust ?? null,
    pioggia_mm: s.rain_tot ?? 0,
    pioggia_max_h: s.rain_max_h ?? 0,
    prob_pioggia: s.prob ?? 0,
    nuvolosita: s.nuvolosita_diurna ?? s.nuvolosita ?? null,
    cielo: s.cielo || 'n/d',
    umidita: s.umidita ?? null,
    convezione: s.convezione || 'assente',
    finestra_pioggia: s.finestra_pioggia || null,
    finestra_vento: s.finestra_vento || null,
    foehn: s.foehn || null,
    inversione: s.inversione || null,
    ...extra,

    uff_cielo: uff.cielo || tend.previsioni || '',
    uff_affidabilita: uff.affidabilita || tend.affidabilita || ''
  };
});

// --- 4. avvisi diagnostici (finiscono nel piè di pagina della mail) ---------
const avvisi = [];
if (contesto.ufficiale_nota) avvisi.push(contesto.ufficiale_nota);
const falliti = contesto.micro_agenti_falliti || [];
if (falliti.length) avvisi.push(`Micro-agenti non disponibili: ${falliti.length} su 2.`);

const troppoCorte = giorni.filter(g => g.descrizione.split(/\s+/).length < 35).length;
if (troppoCorte) avvisi.push(`${troppoCorte} descrizioni più brevi del previsto.`);

return [{
  json: {
    forecast: {
      citta: citta.nome,
      profilo: citta.profilo,
      riquadro,
      quadro_generale: ripulisciTesto(data.quadro_generale),
      confronto_ufficiale: ripulisciTesto(data.confronto_ufficiale || data.confronto_arpal),
      confidenza: ['Alta', 'Media', 'Bassa'].includes(data.confidenza) ? data.confidenza : 'Media',
      giorni
    },
    meta: {
      fonte: contesto.ufficiale_nome || null,
      bollettino: contesto.ufficiale_numero || null,
      emissione: contesto.ufficiale_emissione || null,
      quota: citta.quota,
      quota_modello: contesto.quota_modello ?? null,
      giorni: dateKeys,
      avvisi
    },
    emails: contesto.emails,
    chat_id: contesto.chat_id
  }
}];

// ============================================================================
// FORMATTA HTML (+ versione testuale)
// ============================================================================
// La quarta casella cambia secondo il profilo della località:
//   costa      -> 🌊 Mare
//   pianura    -> 🌫️ Visibilità
//   montagna   -> 🏔️ Zero termico e neve
//   fondovalle -> 🏔️ Zero termico e neve
// ============================================================================

const src = $input.first().json;
const f = src.forecast || {};
const meta = src.meta || {};

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const num = (v, unita = '', dec = 0) =>
  (v === null || v === undefined || v === '' || Number.isNaN(Number(v)))
    ? 'n/d' : `${Number(v).toFixed(dec)}${unita}`;

const piccolo = t => `<br><span style="font-size:9.5px;font-weight:500;color:#64748b;">${t}</span>`;

// --- quarta casella, dipendente dal profilo --------------------------------
function quartaCasella(g) {
  if (f.riquadro === 'neve') {
    const zt = (g.zero_termico_min != null && g.zero_termico_max != null)
      ? `${Math.round(g.zero_termico_min / 10) * 10}–${Math.round(g.zero_termico_max / 10) * 10} m`
      : 'n/d';
    const neve = g.neve_cm > 0
      ? `neve ${num(g.neve_cm, ' cm', 1)}`
      : (g.neve_al_suolo_cm > 0 ? `manto ${num(g.neve_al_suolo_cm, ' cm')}` : 'niente neve');
    return { bg: '#eef2ff', bd: '#c7d2fe', fg: '#4338ca', tit: '🏔️ Zero term.', val: `${zt}${piccolo(neve)}` };
  }
  if (f.riquadro === 'visibilita') {
    const vis = g.vis_min != null
      ? (g.vis_min >= 1000 ? `${(g.vis_min / 1000).toFixed(1)} km` : `${Math.round(g.vis_min)} m`)
      : 'n/d';
    const nota = g.nebbia ? `nebbia ${esc(g.nebbia)}` : (g.foschia ? `foschia ${esc(g.foschia)}` : 'buona');
    return { bg: '#f5f3ff', bd: '#ddd6fe', fg: '#6d28d9', tit: '🌫️ Visibilità', val: `${vis}${piccolo(nota)}` };
  }
  return { bg: '#f0fdf4', bd: '#bbf7d0', fg: '#15803d', tit: '🌊 Mare', val: esc(g.mare || 'Non disponibile') };
}

function boxPioggia(g) {
  const tot = num(g.pioggia_mm, ' mm', 1);
  if (!g.pioggia_mm) return `${tot}${piccolo(`prob. ${num(g.prob_pioggia, '%')}`)}`;
  return `${tot}${piccolo(`max ${num(g.pioggia_max_h, ' mm/h', 1)} · prob. ${num(g.prob_pioggia, '%')}`)}`;
}

function statsTableHtml(g) {
  const celle = [
    { bg: '#f0f9ff', bd: '#bae6fd', fg: '#0369a1', tit: '🌡️ Temp',
      val: `${num(g.tmin, '°', 1)} / ${num(g.tmax, '°C', 1)}${piccolo(`perc. ${num(g.perc_min, '°', 1)} / ${num(g.perc_max, '°C', 1)}`)}` },
    { bg: '#f0fdfa', bd: '#99f6e4', fg: '#0f766e', tit: '🌧️ Pioggia', val: boxPioggia(g) },
    { bg: '#f8fafc', bd: '#e2e8f0', fg: '#475569', tit: '💨 Vento',
      val: `${esc(g.vento_dir)} ${num(g.vento_kmh, ' km/h')}${piccolo(`raff. ${num(g.raffiche_kmh, ' km/h')}${g.finestra_vento ? ` · ${esc(g.finestra_vento)}` : ''}`)}` },
    quartaCasella(g)
  ];

  return `
    <table width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px; border-collapse:separate; border-spacing:4px 0;">
      <tr>${celle.map(c => `
        <td width="25%" valign="top" style="background:${c.bg}; border:1px solid ${c.bd}; border-radius:6px; padding:6px 3px; text-align:center;">
          <div style="font-size:9.5px; font-weight:700; color:${c.fg}; text-transform:uppercase; margin-bottom:2px;">${c.tit}</div>
          <div style="font-size:10.5px; font-weight:600; color:#0f172a; line-height:1.3;">${c.val}</div>
        </td>`).join('')}
      </tr>
    </table>`;
}

// Riga di sintesi: cielo, umidità e i fenomeni locali effettivamente attivi.
function rigaSintesi(g) {
  const pezzi = [`Cielo: ${esc(g.cielo)}`];
  if (g.nuvolosita != null) pezzi.push(`copertura ${num(g.nuvolosita, '%')}`);
  if (g.umidita != null) pezzi.push(`UR ${num(g.umidita, '%')}`);
  if (g.finestra_pioggia) pezzi.push(`fenomeni ore ${esc(g.finestra_pioggia)}`);
  if (g.convezione && g.convezione !== 'assente') pezzi.push(`convezione ${esc(g.convezione)}`);
  if (g.foehn) pezzi.push(`foehn ${esc(g.foehn)}`);
  if (g.inversione) pezzi.push(`inversione ${esc(g.inversione)}`);
  return `<div style="font-size:11px; color:#64748b; margin-top:8px;">${pezzi.join(' · ')}</div>`;
}

const cronoHtml = (f.giorni || []).map(g => `
      <div style="background:#ffffff; border:1px solid #e2e8f0; border-left:4px solid #0284c7; padding:12px 14px; margin-bottom:12px; border-radius:0 8px 8px 0; font-size:13px; line-height:1.55; color:#334155;">
        <strong style="color:#0f172a;">${esc(g.titolo)}:</strong> ${esc(g.descrizione)}
        ${rigaSintesi(g)}
        ${statsTableHtml(g)}
      </div>`).join('');

const fonte = meta.bollettino
  ? `Fonte ufficiale: ${esc(meta.fonte)}, bollettino n° ${esc(meta.bollettino)} (emissione ${esc(meta.emissione || 'n/d')}).`
  : 'Fonte ufficiale non disponibile in questa esecuzione.';

const avvisiHtml = (meta.avvisi || []).length
  ? `<div style="max-width:620px;margin:0 auto 18px auto;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:10px 14px;color:#991b1b;font-size:11.5px;line-height:1.5;">
       <strong>Note di elaborazione:</strong> ${esc((meta.avvisi || []).join(' · '))}
     </div>` : '';

const fullEmailHtml = `
<!DOCTYPE html>
<html lang="it">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bollettino Meteo — ${esc(f.citta)}</title>
</head>
<body style="margin:0; padding:20px 10px; background-color:#f1f5f9; font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <div style="max-width:620px; margin:0 auto;">
    <div style="text-align:center; margin-bottom:22px;">
      <h1 style="color:#0f172a; font-size:20px; font-weight:800; margin:0 0 4px 0; letter-spacing:-0.3px;">🌤️ Bollettino meteorologico</h1>
      <div style="color:#64748b; font-size:12.5px; font-weight:500;">${esc(f.citta)} · ${num(meta.quota, ' m s.l.m.')} · ${(meta.giorni || []).length} giorni</div>
    </div>
    ${avvisiHtml}
    <div style="background:#ffffff; border:1px solid #e2e8f0; border-radius:12px; margin-bottom:28px; overflow:hidden; box-shadow:0 4px 6px -1px rgba(0,0,0,0.05);">
      <div style="background:linear-gradient(135deg, #0284c7, #0369a1); padding:14px 18px; color:#ffffff;">
        <h2 style="margin:0; font-size:17px; font-weight:700; letter-spacing:0.3px;">📍 ${esc(String(f.citta || '').toUpperCase())}</h2>
      </div>
      <div style="padding:18px;">
        <div style="margin-bottom:18px;">
          <div style="font-size:11px; font-weight:700; text-transform:uppercase; color:#0284c7; letter-spacing:0.5px; margin-bottom:4px;">Dinamica delle masse d'aria</div>
          <p style="margin:0; font-size:13.5px; line-height:1.6; color:#334155;">${esc(f.quadro_generale)}</p>
        </div>
        <div style="margin-bottom:18px;">
          <div style="font-size:11px; font-weight:700; text-transform:uppercase; color:#0284c7; letter-spacing:0.5px; margin-bottom:8px;">Cronologia giorno per giorno</div>
          ${cronoHtml}
        </div>
        <div style="background:#fffbeb; border:1px solid #fef3c7; border-left:4px solid #f59e0b; border-radius:6px; padding:10px 14px; font-size:12.5px; line-height:1.5; color:#92400e;">
          <div style="font-weight:700; margin-bottom:3px; color:#b45309;">⚖️ Confronto modelli vs fonte ufficiale</div>
          <strong style="color:#0f172a;">Confidenza ${esc(f.confidenza || 'N/D')}:</strong> ${esc(f.confronto_ufficiale)}
        </div>
      </div>
    </div>
    <div style="text-align:center; color:#94a3b8; font-size:11px; line-height:1.5; margin-top:20px;">
      Elaborazione automatica: AROME HD / ICON-D2 / ICON-2I / ECMWF IFS / GFS.<br>
      ${fonte}<br>
      I valori numerici sono calcolati da script, non generati dal modello linguistico.
    </div>
  </div>
</body>
</html>`;

// --- versione solo testo ----------------------------------------------------
const righe = [`BOLLETTINO METEO — ${f.citta}`, fonte, ''];
righe.push(f.quadro_generale || '');
(f.giorni || []).forEach(g => {
  righe.push('', `${g.titolo}: ${g.descrizione}`);
  const parti = [
    `Temp ${num(g.tmin, '', 1)}/${num(g.tmax, '°C', 1)} (perc. ${num(g.perc_min, '', 1)}/${num(g.perc_max, '°C', 1)})`,
    `Pioggia ${num(g.pioggia_mm, ' mm', 1)} (prob. ${num(g.prob_pioggia, '%')})`,
    `Vento ${g.vento_dir} ${num(g.vento_kmh, ' km/h')} raff. ${num(g.raffiche_kmh, ' km/h')}`
  ];
  if (f.riquadro === 'mare') parti.push(`Mare: ${g.mare}`);
  if (f.riquadro === 'neve') parti.push(`Zero termico ${num(g.zero_termico_min, '', 0)}–${num(g.zero_termico_max, ' m', 0)}, neve ${num(g.neve_cm, ' cm', 1)}`);
  if (f.riquadro === 'visibilita') parti.push(`Visibilità min ${num(g.vis_min, ' m')}${g.nebbia ? ` (nebbia ${g.nebbia})` : ''}`);
  righe.push('  ' + parti.join(' · '));
});
righe.push('', `Confidenza ${f.confidenza}: ${f.confronto_ufficiale || ''}`);
if ((meta.avvisi || []).length) righe.push('', 'Note: ' + meta.avvisi.join(' · '));

return [{
  json: {
    html: fullEmailHtml,
    text: righe.join('\n'),
    citta: f.citta,
    emails: src.emails,
    chat_id: src.chat_id,
    meta
  }
}];
